package com.idfc.ai.runbook.agent;
import com.idfc.ai.runbook.config.RunbookProperties; import java.io.*; import java.nio.charset.StandardCharsets; import java.nio.file.*; import java.util.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.context.annotation.*; import org.springframework.stereotype.Component;
@Component @Profile("!test") @ConditionalOnProperty(name="runbook.agent.type",havingValue="local",matchIfMissing=true) public class LocalIdfcCoderExecutor implements IdfcCoderExecutor { private final RunbookProperties p; public LocalIdfcCoderExecutor(RunbookProperties p){this.p=p;} public IdfcCoderResult execute(IdfcCoderRequest r){ try { Files.createDirectories(r.outputDirectory()); String instruction="Read the centralized prompt and context supplied below. Treat the current repository as authoritative. Generate exactly "+r.outputDirectory().resolve("runbook-data.json")+" and "+r.outputDirectory().resolve("runbook-evidence.json")+". Do not generate RUNBOOK.md, access Confluence, publish, or modify source.\nPROMPT:\n"+r.prompt()+"\nCONTEXT:\n"+r.context(); Process process=new ProcessBuilder(p.getAgent().getExecutable(),instruction).directory(r.repository().toFile()).start(); boolean done=process.waitFor(p.getAgent().getTimeout().toMillis(),java.util.concurrent.TimeUnit.MILLISECONDS); if(!done){process.destroyForcibly();throw new IllegalStateException("RUNBOOK_AGENT_TIMEOUT");} String out=cap(process.getInputStream().readAllBytes()),err=cap(process.getErrorStream().readAllBytes()); if(process.exitValue()!=0)throw new IllegalStateException("RUNBOOK_AGENT_FAILED"); if(!Files.isRegularFile(r.outputDirectory().resolve("runbook-data.json"))||!Files.isRegularFile(r.outputDirectory().resolve("runbook-evidence.json")))throw new IllegalStateException("RUNBOOK_EXTRACTION_MISSING"); return new IdfcCoderResult(out,err); } catch(IOException e){throw new IllegalStateException("RUNBOOK_AGENT_FAILED",e);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("RUNBOOK_AGENT_TIMEOUT",e);} } private String cap(byte[] b){return new String(b,0,Math.min(b.length,p.getAgent().getMaxCapturedLogBytes()),StandardCharsets.UTF_8);} }
